test('all256 octets and160 lead/next-byte controls preserve all416 original outcomes',async()=>{
  const f=validateRetained(await readFile(fixture))
  const leads=['c0','c1','c2','df','e0','e1','ec','ed','ee','ef','f0','f1','f3','f4','f5','ff']
  const next=['00','7f','80','8f','90','9f','a0','bf','c0','ff']
  const grid=[...Array.from({length:256},(_,byte)=>['byte',byte.toString(16).padStart(2,'0')]),...leads.flatMap(lead=>next.map(second=>['lead-next',lead+second]))]
  const names=grid.map(([category,anchor])=>`utf8-octet-${category}-${anchor}`)
  assert.equal(cases.length,416);assert.equal(cases.reduce((n,c)=>n+rowsFor(c).length,0),832)
  assert.equal(new Set(names).size,416)
  assert.deepEqual(cases.map(c=>c.name),names);assert.deepEqual(observed.map(([name])=>name),names)
  for(const run of f.runs)for(const [i,o]of run.observations.entries()){
    const [category,anchor]=grid[i],oracle=observed[i][1]
    for(const width of ['sourceWidth','wireWidth','targetWidth'])assert.equal(o.case[width],64)
    for(const encoding of ['declared','wire','target'])assert.equal(o.case[encoding],'utf8')
    assert.equal(o.case.category,category);assert.equal(o.case.anchorHex,anchor);assert.equal(o.case.context,'suffix')
    assert.deepEqual(o.input,[{id:1,valueHex:null},{id:2,valueHex:anchor+'42'}])
    assert.deepEqual(o.readback.result.sets[1].rows,oracle.rows,o.case.name)
    assert.deepEqual(o.execution.result.errors.map(e=>[e.number,e.state,e.class]),oracle.errors,o.case.name)
    assert.deepEqual(o.execution.result.info.map(e=>[e.number,e.state,e.class]),oracle.info,o.case.name)
    assert.deepEqual(o.readback.result.sets[0].rows,oracle.counters,o.case.name)
    assert.equal(o.readback.session,'original');assert.equal(o.recoveryReadback,undefined)
    assert.equal(o.execution.result.error,null);assert.equal(o.execution.result.rowCount,2)
    assert.deepEqual(oracle.errors,[]);assert.deepEqual(oracle.info,[]);assert.deepEqual(oracle.counters,[[0,2,0,0]])
    assert.deepEqual(oracle.rows[0],[1,null,null,null,null]);assert.equal(oracle.rows[1][2].value,anchor+'42')
  }
  const replay=spawnSync(process.execPath,['scripts/capture-bulk-character-utf8-octet.mjs','--replay-fixture'],{cwd:new URL('../',import.meta.url),encoding:'utf8',env:{...process.env,PATH:''},timeout:15000})
  assert.equal(replay.status,0,replay.stderr)
})

test('uniform byte-grid/type/native/unit/counter/provenance corruption and omitted probes fail fixed pins',async()=>{
  const retained=await load()
  const changes=[
    ['utf8-octet-byte-41',o=>{o.execution.result.rowCount=99}],
    ['utf8-octet-lead-next-c280',o=>{o.case.sourceWidth='max'}],
    ['utf8-octet-lead-next-e080',o=>{o.readback.result.sets[1].rows[1][4].value='fdfffdff4200'}],
    ['utf8-octet-lead-next-e080',o=>{o.readback.result.sets[1].rows[1][2].value='efbfbdefbfbd42'}],
    ['utf8-octet-byte-80',o=>{o.readback.result.sets[0].rows[0][0]=9833}],
    ['utf8-octet-lead-next-c280',o=>{o.metadata.result.sets[0].columns[0].length=65535}],
    ['utf8-octet-byte-41',o=>{o.case.anchorHex='42'}]
  ]
  for(const [name,mutate]of changes){const f=structuredClone(retained);for(const run of f.runs)mutate(find(run,name));f.comparisons=f.runs.slice(1).map(r=>compare(r,f.runs[0]));assert.throws(()=>validate(f),/fixed/)}
  const omitted=structuredClone(retained);for(const run of omitted.runs)run.observations.pop();omitted.comparisons=omitted.runs.slice(1).map(r=>compare(r,omitted.runs[0]));assert.throws(()=>validate(omitted))
  for(const field of ['sourceSha','helperSha','nodeVersion']){const f=structuredClone(retained);f.provenance[field]='0'.repeat(64);assert.throws(()=>validate(f),/fixed/)}
  const f=structuredClone(retained);f.provenance.helpers['capture-bulk-character-utf8-context.mjs']='0'.repeat(64);assert.throws(()=>validate(f),/fixed/)
})

test('overlapping suffix inputs preserve original outcomes without inheriting isolated-anchor errors',async()=>{
  const f=await load(),bytes=await readCaptureFile(new URL('../reference/bulk-character-utf8-context.json',import.meta.url))
  assert.equal(createHash('sha256').update(bytes).digest('hex'),'cd27cbeb9549b1109eaa85fc31417b234dad1140a6f830d65ba9ba9daafbf0d0')
  const old=JSON.parse(bytes)
  for(const [ri,run]of f.runs.entries())for(const [name,category,anchor]of [['byte-80','illegal-lead','80'],['byte-bf','illegal-lead','bf'],['byte-c2','truncated','c2'],['lead-next-c1bf','illegal-lead','c1bf']]){
    const o=find(run,`utf8-octet-${name}`),previous=find(old.runs[ri],`utf8-context-${category}-${anchor}-suffix-source64-to-utf864`)
    assert.deepEqual(o.input,previous.input)
    assert.deepEqual(o.readback.result.sets.map(s=>s.rows),previous.readback.result.sets.map(s=>s.rows))
    assert.deepEqual(o.readback.result.sets.map(s=>s.columns),previous.readback.result.sets.map(s=>s.columns))
    assert.deepEqual(o.execution.result,previous.execution.result)
    assert.notEqual(o.case.name,previous.case.name);assert.notEqual(o.readback.sql,previous.readback.sql)
  }
})
